const raw = $input.first().json.content?.find(b=>b.type==='text')?.text || '';
const clean = raw.replace(/```json|```/g,'').trim();
let parsed;
try { parsed = JSON.parse(clean); }
catch(e) {
  const match = clean.match(/\{[\s\S]*\}/);
  if (match) { try { parsed = JSON.parse(match[0]); } catch(e2) { throw new Error('Cannot parse: ' + clean.slice(0,200)); } }
  else throw new Error('No JSON found: ' + clean.slice(0,200));
}
const si = $('Sanitize Inputs').first().json;
return [{json: {
  caption:       parsed.caption || '',
  hashtags:      parsed.hashtags || '#ArakLighting #LightingDesign',
  image_prompt:  parsed.image_prompt || '',
  post_strategy: parsed.post_strategy || '',
  topic:         si.safe_topic,
  tone:          si.tone,
  style:         si.style,
  content_route: si.content_route,
}}];

const styleMap = {
  "photorealistic":   "architectural photography, Canon EOS R5, natural lighting, hyper-detailed, 4K",
  "dramatic":         "cinematic lighting, deep shadows, god rays, high contrast, noir atmosphere",
  "minimalist":       "clean lines, soft diffused light, Scandinavian aesthetic, white space, elegant",
  "warm_residential": "warm amber tones, cozy luxury interior, golden hour, warm white light 2700K",
  "cool_commercial":  "cool white 5000K, modern commercial space, crisp, corporate luxury",
  "facade_exterior":  "architectural exterior night photography, facade illumination, dramatic night sky"
};
const customMap = {
  "event_poster":      "professional event poster design, bold promotional graphic with text overlay space, dramatic stage lighting, gold and dark luxury color scheme, Saudi Arabia",
  "hiring_poster":     "modern recruitment poster, professional corporate layout, inspiring office background Saudi Arabia",
  "product_showcase":  "studio product photography, lighting fixture on pure black background, dramatic spotlight",
  "project_highlight": "architectural interior photography, completed luxury project, golden hour, Saudi Arabia",
  "quote_card":        "elegant minimal quote card, dark background with warm accent lighting bokeh, luxury brand",
  "suppliers_collab":  "corporate partnership announcement, premium product display, luxury lighting showroom Saudi Arabia",
  "behind_scenes":     "documentary photography, lighting installation on-site, team working, Saudi Arabia",
  "ai_decides":        ""
};
const si = $('Sanitize Inputs').first().json;
const routeType  = si.route_type;
const topic      = si.safe_topic || '';
const visualMode = si.visual_mode;
const customType = si.custom_type;
const style      = si.style;
let imagePrompt, finalPrompt;
if (routeType === 'image_only') {
  const rewritten = $('Claude: Rewrite Image Prompt').first().json.content?.find(b=>b.type==='text')?.text || si.image_prompt;
  imagePrompt = rewritten.trim();
  finalPrompt = imagePrompt + ', Arak Lighting Saudi Arabia, ultra high detail';
} else if (visualMode === 'custom' && customType) {
  const base = $('Parse Caption').first().json.image_prompt || topic;
  const mod  = customMap[customType] || '';
  finalPrompt = mod ? (topic + ' — ' + base + ', ' + mod + ', Arak Lighting Saudi Arabia, ultra high detail') : (base + ', Arak Lighting Saudi Arabia, award-winning photography');
  imagePrompt = base;
} else if (visualMode === 'lighting' && style) {
  const base = $('Parse Caption').first().json.image_prompt || topic;
  const mod  = styleMap[style] || styleMap['photorealistic'];
  finalPrompt = base + ', ' + mod + ', Arak Lighting Saudi Arabia, luxury architectural lighting';
  imagePrompt = base;
} else {
  const base = $('Parse Caption').first().json.image_prompt || topic;
  finalPrompt = base + ', Arak Lighting Saudi Arabia, luxury architectural lighting, ultra high detail';
  imagePrompt = base;
}
return [{json: { final_prompt: finalPrompt, style: style || 'auto', image_prompt: imagePrompt, visual_mode: visualMode, custom_type: customType }}];

